// Template: password_reset_requested/fr — rendu inline (versionné dans /n8n/email-templates)
const input = $('Execute Workflow Trigger').first().json;
const payload = input.payload || input;
const d = payload.data || {};

const SUBJECT_TPL = "R\u00e9initialisation de votre mot de passe Contravo";
const BODY_MJML = "<mjml><mj-body><mj-section><mj-column>\n      <mj-text>Bonjour {{fullName}},</mj-text>\n      <mj-text>Vous avez demand\u00e9 la r\u00e9initialisation de votre mot de passe Contravo. Ce lien expire dans {{expiresInMinutes}} minutes et ne fonctionne qu'une seule fois.</mj-text>\n      <mj-button href=\"{{resetUrl}}\">D\u00e9finir un nouveau mot de passe</mj-button>\n      <mj-text>Si vous n'\u00eates pas \u00e0 l'origine de cette demande, ignorez cet email : votre mot de passe actuel reste valable.</mj-text>\n      <mj-text>Contravo</mj-text>\n    </mj-column></mj-section></mj-body></mjml>\n";

const ctx = {
  ...d,
  fullName: d.fullName || '',
  resetUrl: d.resetUrl || '',
  expiresInMinutes: d.expiresInMinutes || 60,
};

function lookup(path) {
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), ctx);
}
function resolve(tpl) {
  return tpl.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, p) => {
    const v = lookup(p);
    return v == null ? '' : String(v);
  });
}

// MJML -> HTML. mjml est optionnel dans l'image n8n : fallback si absent.
function compile(mjmlSource) {
  try {
    const mjml2html = require('mjml');
    const out = mjml2html(mjmlSource, { validationLevel: 'soft' });
    if (out && out.html) return out.html;
  } catch (e) {
    // mjml non installé -> dégradation contrôlée vers un HTML simple
  }
  const body = mjmlSource
    .replace(/<mj-button[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/mj-button>/g,
             '<p><a href="$1">$2</a></p>')
    .replace(/<mj-text[^>]*>([\s\S]*?)<\/mj-text>/g, '<p>$1</p>')
    .replace(/<\/?mj-(?:mjml|body|section|column|raw)[^>]*>/g, '')
    .replace(/<\/?mjml[^>]*>/g, '');
  return '<!doctype html><html><body>' + body + '</body></html>';
}

const to = [d.email].filter(Boolean);
if (!to.length) {
  throw new Error('Aucun destinataire résolu pour password_reset_requested (event ' + (payload.id || '?') + ')');
}
if (!d.resetUrl) {
  throw new Error('resetUrl absent : un email sans lien de réinitialisation est inutile');
}

return [{ json: {
  eventId: payload.id || '',
  to,
  subject: resolve(SUBJECT_TPL).trim(),
  html: compile(resolve(BODY_MJML)),
} }];
